INSERT INTO reviews (id, title, year, rating, genre, poster, body, created_at, updated_at) VALUES
  ('sample-last-screening', '마지막 상영', 2025, 5, '드라마', '/seed/last-screening-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"문 닫는 동네 극장의 마지막 밤을 그린 이 영화는 큰 사건 없이도 끝까지 시선을 붙잡는다."}]},{"type":"image","attrs":{"src":"/seed/last-screening-scene.svg","alt":"붉은 노을 아래 지평선 위로 해가 걸린 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"영사기 돌아가는 소리와 객석의 숨소리만으로 쌓아 올린 후반 20분은 올해 본 가장 아름다운 장면이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-10-28T09:00:00Z', '2026-10-28T09:00:00Z'),
  ('sample-winter-route', '겨울의 항로', 2024, 4, '드라마', '/seed/winter-route-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"얼어붙은 바다를 건너는 쇄빙선 선원들의 이야기. 느린 호흡이 지루함과 긴장 사이를 아슬아슬하게 오간다."}]},{"type":"image","attrs":{"src":"/seed/winter-route-scene.svg","alt":"차가운 푸른빛 바다 위로 낮은 해가 뜬 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"결말은 호불호가 갈리겠지만, 화면에 담긴 추위만큼은 객석까지 그대로 전해진다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-10-21T09:00:00Z', '2026-10-21T09:00:00Z'),
  ('sample-neon-rain', '네온 레인', 2026, 3, '스릴러', '/seed/neon-rain-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"비에 젖은 도심을 달리는 추격 장면까지는 근래 스릴러 가운데 가장 날카롭다."}]},{"type":"image","attrs":{"src":"/seed/neon-rain-scene.svg","alt":"보랏빛 비가 내리는 밤거리 풍경"}},{"type":"paragraph","content":[{"type":"text","text":"다만 반전을 설명하는 마지막 10분이 앞서 쌓은 긴장을 스스로 풀어 버린다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-10-14T09:00:00Z', '2026-10-14T09:00:00Z'),
  ('sample-silent-floor', '조용한 층', 2025, 4, '스릴러', '/seed/silent-floor-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"야근하는 직원들만 남은 빌딩에서 벌어지는 실종 사건을 다룬다. 공간을 다루는 솜씨가 빼어나다."}]},{"type":"image","attrs":{"src":"/seed/silent-floor-scene.svg","alt":"불 꺼진 사무실 복도 끝의 희미한 불빛"}},{"type":"paragraph","content":[{"type":"text","text":"소리를 덜어낸 연출 덕분에 관객은 어느새 숨을 죽이고 복도 끝을 살피게 된다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-10-07T09:00:00Z', '2026-10-07T09:00:00Z'),
  ('sample-glass-orbit', '유리 궤도', 2026, 5, 'SF', '/seed/glass-orbit-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"궤도 정거장에 홀로 남은 관측원의 기록. 거대한 설정보다 한 사람의 고독에 집중한 선택이 빛난다."}]},{"type":"image","attrs":{"src":"/seed/glass-orbit-scene.svg","alt":"행성 위로 떠오르는 푸른 빛"}},{"type":"paragraph","content":[{"type":"text","text":"우주를 비추는 긴 고정 숏은 근래 SF가 잊고 있던 경외감을 되살린다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-09-30T09:00:00Z', '2026-09-30T09:00:00Z'),
  ('sample-second-sun', '두 번째 태양', 2024, 3, 'SF', '/seed/second-sun-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"설정은 흥미롭지만 세계관 설명에 러닝타임을 너무 많이 쓴다."}]},{"type":"image","attrs":{"src":"/seed/second-sun-scene.svg","alt":"사막 위로 뜬 두 개의 태양"}},{"type":"paragraph","content":[{"type":"text","text":"그럼에도 황량한 사막을 담은 미술만큼은 큰 화면으로 볼 가치가 있다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-09-23T09:00:00Z', '2026-09-23T09:00:00Z'),
  ('sample-spring-letter', '봄의 답장', 2025, 4, '로맨스', '/seed/spring-letter-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"편지로만 이어지는 두 사람의 십 년을 담담하게 따라간다."}]},{"type":"image","attrs":{"src":"/seed/spring-letter-scene.svg","alt":"벚꽃이 흩날리는 강변 산책로"}},{"type":"paragraph","content":[{"type":"text","text":"두 배우가 한 화면에 서는 장면은 단 하나뿐인데, 그 한 장면을 위해 모든 시간이 쌓인다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-09-16T09:00:00Z', '2026-09-16T09:00:00Z'),
  ('sample-midnight-bakery', '자정의 빵집', 2023, 3, '로맨스', '/seed/midnight-bakery-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"달콤한 설정에 기대는 순간이 많지만 배우들의 호흡이 그 약점을 대부분 덮는다."}]},{"type":"image","attrs":{"src":"/seed/midnight-bakery-scene.svg","alt":"불 켜진 빵집 창문 너머의 밤거리"}},{"type":"paragraph","content":[{"type":"text","text":"가볍게 즐기기에는 부족함이 없는 소품이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-09-09T09:00:00Z', '2026-09-09T09:00:00Z'),
  ('sample-wrong-wedding', '엉뚱한 결혼식', 2025, 4, '코미디', '/seed/wrong-wedding-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"잘못 배달된 청첩장 한 장에서 시작하는 소동극. 타이밍으로 웃기는 법을 아는 드문 코미디다."}]},{"type":"image","attrs":{"src":"/seed/wrong-wedding-scene.svg","alt":"하객 없는 결혼식장에 놓인 빈 의자들"}},{"type":"paragraph","content":[{"type":"text","text":"중반의 식탁 장면은 혼자 봐도 소리 내어 웃게 된다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-09-02T09:00:00Z', '2026-09-02T09:00:00Z'),
  ('sample-office-picnic', '사무실 소풍', 2024, 2, '코미디', '/seed/office-picnic-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"직장 풍자로 시작하지만 같은 농담을 반복하다 힘을 잃는다."}]},{"type":"image","attrs":{"src":"/seed/office-picnic-scene.svg","alt":"회의실에 펼쳐 놓은 돗자리"}},{"type":"paragraph","content":[{"type":"text","text":"조연들의 즉흥 연기가 아니었다면 끝까지 보기 어려웠을 것이다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-08-26T09:00:00Z', '2026-08-26T09:00:00Z'),
  ('sample-iron-harbor', '철의 항구', 2026, 4, '액션', '/seed/iron-harbor-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"컨테이너 부두 한 곳에서 90분을 버티는 액션. 합을 끊지 않는 촬영이 체력의 한계까지 보여 준다."}]},{"type":"image","attrs":{"src":"/seed/iron-harbor-scene.svg","alt":"화물 컨테이너가 쌓인 항구의 해질녘"}},{"type":"paragraph","content":[{"type":"text","text":"서사는 단순하지만 몸으로 쓴 장면들이 그 단순함을 오히려 장점으로 만든다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-08-19T09:00:00Z', '2026-08-19T09:00:00Z'),
  ('sample-night-express', '야간 급행', 2023, 3, '액션', '/seed/night-express-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"달리는 열차라는 익숙한 무대를 성실하게 활용한다. 새롭지는 않아도 지루할 틈은 없다."}]},{"type":"image","attrs":{"src":"/seed/night-express-scene.svg","alt":"어둠 속을 달리는 열차의 창문 불빛"}},{"type":"paragraph","content":[{"type":"text","text":"후반의 객차 분리 장면은 충분히 기억할 만하다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-08-12T09:00:00Z', '2026-08-12T09:00:00Z'),
  ('sample-salt-makers', '소금을 만드는 사람들', 2025, 5, '다큐멘터리', '/seed/salt-makers-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"사라져 가는 염전의 한 해를 내레이션 없이 기록한다. 인내심 있는 카메라가 노동의 리듬을 그대로 옮긴다."}]},{"type":"image","attrs":{"src":"/seed/salt-makers-scene.svg","alt":"해 질 무렵 염전에 비친 하늘"}},{"type":"paragraph","content":[{"type":"text","text":"마지막 수확 장면에 이르면 소금 한 줌의 무게가 다르게 느껴진다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-08-05T09:00:00Z', '2026-08-05T09:00:00Z'),
  ('sample-city-of-pigeons', '비둘기의 도시', 2024, 3, '다큐멘터리', '/seed/city-of-pigeons-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"도심 비둘기와 함께 사는 사람들을 따라간다. 소재의 재미에 비해 구성은 다소 느슨하다."}]},{"type":"image","attrs":{"src":"/seed/city-of-pigeons-scene.svg","alt":"광장 위를 나는 비둘기 떼"}},{"type":"paragraph","content":[{"type":"text","text":"그래도 노년의 사육사가 전하는 이야기만큼은 오래 남는다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-07-29T09:00:00Z', '2026-07-29T09:00:00Z'),
  ('sample-paper-whale', '종이 고래', 2026, 5, '애니메이션', '/seed/paper-whale-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"손으로 접은 종이의 질감을 그대로 살린 화면이 시작부터 눈을 사로잡는다."}]},{"type":"image","attrs":{"src":"/seed/paper-whale-scene.svg","alt":"종이로 접은 고래가 헤엄치는 밤하늘"}},{"type":"paragraph","content":[{"type":"text","text":"어린 관객을 얕보지 않는 이야기 덕분에 어른에게 더 깊게 남는다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-07-22T09:00:00Z', '2026-07-22T09:00:00Z'),
  ('sample-little-lighthouse', '작은 등대', 2023, 4, '애니메이션', '/seed/little-lighthouse-poster.svg', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"바닷가 마을의 등대를 지키는 아이의 모험. 단순한 그림체가 오히려 감정을 또렷하게 전한다."}]},{"type":"image","attrs":{"src":"/seed/little-lighthouse-scene.svg","alt":"파도 위로 빛을 비추는 작은 등대"}},{"type":"paragraph","content":[{"type":"text","text":"음악과 파도 소리의 조화가 특히 좋다."}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"italic"}],"text":"이 글은 포트폴리오를 위해 지어낸 가상의 영화 리뷰입니다."}]}]}'::jsonb, '2026-07-15T09:00:00Z', '2026-07-15T09:00:00Z');
